#include <iostream>

int main()
{
    long long n{};
    if (!(std::cin >> n)) return 0;

    int steps{};

    while (n != 1)
    {
        if (n % 2 == 0)
            n /= 2;
        else
            n = 3 * n + 1;
        ++steps;
    }

    std::cout << "steps " << steps << "\n";

    return 0;
}
